+  --accent-tint: #fafbfc;
+  --accent-hover: #1c2535;
+  --brand: #e04e28;
+  --brand-weak: #f4b8a4; /* derived */
+  --brand-soft: #fbe8e1;
+  --brand-text: #b93a1b; /* derived: KnowMe ember-2 (#c13e1e) is 4.46:1 on its ember-soft, just under AA */
