+  --brand-surface: #fbe8e1;
+
+  --green: #16a34a;
+  --green-bg: color-mix(in srgb, #16a34a 12%, #ffffff);
+  --green-border: color-mix(in srgb, #16a34a 34%, #e5e8ed);
+  --blue: #0891b2;
+  --blue-bg: color-mix(in srgb, #0891b2 12%, #ffffff);
+  --blue-border: color-mix(in srgb, #0891b2 34%, #e5e8ed);
