+  --purple-bg: #f2f4f7;
+  --purple-border: #e5e8ed;
+  --red: #dc2626;
+  --red-bg: color-mix(in srgb, #dc2626 12%, #ffffff);
+  --red-border: color-mix(in srgb, #dc2626 34%, #e5e8ed);
+  --amber: #d97706;
+  --amber-bg: color-mix(in srgb, #d97706 14%, #ffffff);
