+  --send-ground: #ff6a3d;
+  --send-ink: #0b0f14;
+  --upgrade-ground: #ff6a3d;
+  --upgrade-ink: #0b0f14;
+}
+
+/* Dark: explicit theme. */
+html[data-brand="knowdesign"][data-theme="dark"] {
+  color-scheme: dark;
+  --bg: #0b0f14;
+  --bg-app: #0b0f14;
+  --bg-panel: #111620;
+  --bg-subtle: #161d29;
+  --bg-muted: #1c2535;
+  --bg-elevated: #161d29;
+  --bg-fill-tertiary: rgba(232, 237, 243, 0.04);
