+  --purple-border: #1f2d40;
+  --red: #ef4444;
+  --red-bg: color-mix(in srgb, #ef4444 24%, #0b0f14);
+  --red-border: color-mix(in srgb, #ef4444 34%, #1f2d40);
+  --amber: #f59e0b;
+  --amber-bg: color-mix(in srgb, #f59e0b 22%, #0b0f14);
