+
+    --green: #22c55e;
+    --green-bg: color-mix(in srgb, #22c55e 22%, #0b0f14);
+    --green-border: color-mix(in srgb, #22c55e 34%, #1f2d40);
+    --blue: #00c2dc;
+    --blue-bg: color-mix(in srgb, #00c2dc 22%, #0b0f14);
