+    expect(resolveBrand({ OD_BUILD_PROFILE: "something-else" })).toBe(OPEN_DESIGN_BRAND);
+    expect(resolveBrand({ OD_BUILD_PROFILE: "knowdesign" })).toBe(KNOWDESIGN_BRAND);
